r=pathlib.Path(__file__).parents[1];h=(r/'index.html').read_text();j=(r/'app.js').read_text();c=(r/'styles.css').read_text();d=json.load(open(r/'data/registry.json'));assert d['release']=='8.2.0-full-focused-navigation';assert len(d['modes'])==23 and len(d['sources'])>=6;assert all(x in h for x in ['today','profiles','calendar','history','insights','data','evidence','uncertainty','sources','method','limits','imprint']);assert all(x in j for x in ['renderHistoryList','renderEvidence','largestDriver','exportJson','applyCalendar','weekdays']);assert 'border-radius:50%' in c;assert (r/'data/riskai_registry.sqlite').exists();assert (r/'docs/Personal_Quantitative_Risk_Assessment_PQRA.pdf').exists();con=sqlite3.connect(r/'data/riskai_registry.sqlite');assert con.execute('select count(*) from modes').fetchone()[0]==23;con.close();print('OK RISK-i Full v8.1 Complete')